int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    if (!dctx->frame_start_found) {
        for (int i = 0; i < buf_size - 2; i++) {
            if (buf[i] == 0x00 && buf[i + 1] == 0x00 && buf[i + 2] == 0x01) {
                dctx->frame_start_found = 1;
                dctx->frame_start_index = i;
                break;
            }
        }
    }

    if (dctx->frame_start_found) {
        int frame_offset = dctx->frame_start_index;
        int frame_size = 0;

        if (frame_offset + 4 <= buf_size) {
            uint32_t header = AV_RB32(buf + frame_offset);
            if ((header & 0xFF000000) == 0x1F000000) {
                int cid = (header >> 16) & 0xFF;
                frame_size = dnxhd_get_frame_size(cid);
                if (frame_size > 0 && frame_offset + frame_size <= buf_size) {
                    return buf_size - frame_offset - frame_size;
                }
            }
        }

        if (frame_offset + buf_size < dctx->frame_size) {
            dctx->frame_size = 0;
            return END_NOT_FOUND;
        }

        return dctx->frame_size - (frame_offset + buf_size);
    }

    return END_NOT_FOUND;
}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    if (!dctx->frame_start_found) {
        for (int i = 0; i < buf_size; i++) {
            if (buf[i] == 0x00 && buf[i + 1] == 0x00 && buf[i + 2] == 0x01) {
                dctx->frame_start_found = 1;
                dctx->frame_start = buf + i;
                dctx->frame_offset = i;
                break;
            }
        }
        return END_NOT_FOUND;
    }

    int remaining = dctx->frame_size - dctx->frame_offset;
    if (remaining <= 0) {
        dctx->frame_start_found = 0;
        return 0;
    }

    if (buf_size < remaining) {
        remaining = buf_size;
    }

    dctx->frame_offset += remaining;

    if (dctx->frame_offset >= dctx->frame_size) {
        dctx->frame_start_found = 0;
        return dctx->frame_size;
    }

    return END_NOT_FOUND;
}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    if (!dctx->frame_start_found) {
        for (int i = 0; i < buf_size - 3; i++) {
            if (buf[i] == 0x1F && buf[i + 1] == 0xBC && buf[i + 2] == 0x00) {
                dctx->frame_start_found = 1;
                dctx->frame_start = i + 3;
                break;
            }
        }
    }

    if (dctx->frame_start_found) {
        int remaining_bytes = dctx->frame_size - dctx->frame_offset;
        if (remaining_bytes <= buf_size) {
            dctx->frame_offset += remaining_bytes;
            if (dctx->frame_offset == dctx->frame_size) {
                dctx->frame_start_found = 0;
                return remaining_bytes;
            }
        } else {
            dctx->frame_offset += buf_size;
            return END_NOT_FOUND;
        }
    }

    return END_NOT_FOUND;
}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    if (!dctx->frame_start_found) {
        for (int i = 0; i < buf_size; i++) {
            if (buf[i] == 0x00 && i + 1 < buf_size && buf[i + 1] == 0x00 && i + 2 < buf_size && buf[i + 2] == 0x01) {
                dctx->frame_start_found = 1;
                dctx->frame_start = i + 3;
                break;
            }
        }
    }

    if (dctx->frame_start_found) {
        int bytes_parsed = 0;
        const uint8_t *buf_ptr = buf + dctx->frame_start;

        if (buf_ptr < buf + buf_size) {
            dctx->width = (*buf_ptr << 8) | *(buf_ptr + 1);
            dctx->height = (*buf_ptr + 2 << 8) | *(buf_ptr + 3);
            dctx->remaining_bytes = (*buf_ptr + 4 << 24) | (*buf_ptr + 5 << 16) | (*buf_ptr + 6 << 8) | *(buf_ptr + 7);

            bytes_parsed = dctx->frame_start + 8;
        }

        if (bytes_parsed >= dctx->frame_start + dctx->remaining_bytes) {
            return dctx->frame_start + dctx->remaining_bytes - dctx->frame_start;
        } else if (buf_ptr + dctx->remaining_bytes - bytes_parsed > buf_size) {
            dctx->remaining_bytes -= buf_size;
            return END_NOT_FOUND;
        } else {
            return dctx->remaining_bytes;
        }
    }

    return END_NOT_FOUND;
}
